const db = require("../models");
const inventory = require("../services/inventory.service");

// ✅ Manual stock adjustment (damage, expiry, breakage, physical count,
// opening stock, correction). This is the ONLY way to create a stock
// movement that isn't automatically generated by a confirmed purchase
// delivery (IN) or sales delivery (OUT) — i.e. arbitrary "stockIn"/
// "stockOut" postings that pretend to be PURCHASE or SALES movements are
// not allowed here.
exports.adjustStock = async (req, res) => {
  const t = await db.sequelize.transaction();
  try {
    const { batchId, productId, quantity, direction, reasonType, reason, warehouseId } = req.body;
    const distributorId = req.user.id;

    if (!batchId || !productId || !quantity || quantity <= 0) {
      await t.rollback();
      return res.status(400).json({ message: "batchId, productId and a positive quantity are required" });
    }
    if (!["IN", "OUT"].includes(direction)) {
      await t.rollback();
      return res.status(400).json({ message: "direction must be IN or OUT" });
    }

    const movement = await inventory.postAdjustment({
      distributorId,
      productId,
      batchId,
      quantity,
      direction,
      reasonType: reasonType || "CORRECTION",
      reason,
      warehouseId: warehouseId || null, // Phase 5: optional; default = the distributor's default warehouse
      userId: req.user.id,
      transaction: t,
    });

    await t.commit();
    res.status(201).json({ message: "Stock adjustment posted successfully", movement });
  } catch (err) {
    await t.rollback();
    console.error("Error posting stock adjustment:", err.message);
    const status =
      err instanceof inventory.InsufficientStockError || err instanceof inventory.InventoryValidationError
        ? 400
        : 500;
    res.status(status).json({ error: err.message, details: err.details });
  }
};

// Deprecated aliases kept for route backward-compatibility. Both now route
// through the governed adjustment path above instead of creating arbitrary
// ledger rows.
exports.stockIn = (req, res) => {
  req.body = { ...req.body, direction: "IN", reasonType: req.body.reasonType || "OPENING" };
  return exports.adjustStock(req, res);
};
exports.stockOut = (req, res) => {
  req.body = { ...req.body, direction: "OUT", reasonType: req.body.reasonType || "CORRECTION" };
  return exports.adjustStock(req, res);
};

exports.getAvailableStockByBatch = async (req, res) => {
  try {
    const { batchId } = req.params;
    const distributorId = req.user.id;

    const batch = await db.Batch.findOne({ where: { id: batchId, distributor_id: distributorId } });
    if (!batch) return res.status(404).json({ message: "Batch not found" });

    const available = await inventory.getBatchAvailableQty({ batchId, distributorId });
    res.json({ batchId, available_stock: available });
  } catch (err) {
    console.error("Error fetching batch stock:", err.message);
    res.status(500).json({ error: "Error fetching batch stock" });
  }
};

exports.getCurrentStock = async (req, res) => {
  try {
    const distributorId = req.user.id;

    const ledger = await db.StockLedger.findAll({
      where: { distributor_id: distributorId },
      include: [{ model: db.Product, as: "product" }],
    });

    const result = {};
    for (const entry of ledger) {
      const productId = entry.productId;
      if (!result[productId]) {
        result[productId] = {
          productId,
          productName: entry.product?.name,
          reorderLevel: entry.product?.reorder_level ?? null,
          quantity: 0,
        };
      }
      result[productId].quantity += entry.movement_type === "OUT" ? -entry.quantity : entry.quantity;
    }

    const withFlags = Object.values(result).map((r) => ({
      ...r,
      isOutOfStock: r.quantity <= 0,
      isLowStock: r.reorderLevel != null && r.quantity > 0 && r.quantity <= r.reorderLevel,
    }));

    res.json(withFlags);
  } catch (err) {
    console.error("Error fetching current stock:", err.message);
    res.status(500).json({ error: "Error fetching current stock" });
  }
};

exports.getBatchStock = async (req, res) => {
  try {
    const distributorId = req.user.id;

    const ledger = await db.StockLedger.findAll({
      where: { distributor_id: distributorId },
      include: [
        { model: db.Product, as: "product" },
        { model: db.Batch, as: "batch" },
      ],
    });

    const result = {};
    const now = new Date();
    for (const entry of ledger) {
      const key = entry.batchId;
      if (!result[key]) {
        result[key] = {
          batchId: entry.batchId,
          batchNo: entry.batch?.batch_no,
          productId: entry.productId,
          productName: entry.product?.name,
          expDate: entry.batch?.exp_date || null,
          batchStatus: entry.batch?.status || null,
          quantity: 0,
        };
      }
      result[key].quantity += entry.movement_type === "OUT" ? -entry.quantity : entry.quantity;
    }

    const withFlags = Object.values(result).map((r) => ({
      ...r,
      isExpired: r.expDate ? new Date(r.expDate) < now : false,
      isOutOfStock: r.quantity <= 0,
    }));

    res.json(withFlags);
  } catch (err) {
    console.error("Error fetching batch stock:", err.message);
    res.status(500).json({ error: "Error fetching batch stock" });
  }
};

exports.getStockLedger = async (req, res) => {
  try {
    const distributorId = req.user.id;

    const ledger = await db.StockLedger.findAll({
      where: { distributor_id: distributorId },
      include: [
        { model: db.Product, as: "product" },
        { model: db.Batch, as: "batch" },
      ],
      order: [["createdAt", "DESC"]],
    });

    res.json(ledger);
  } catch (err) {
    console.error("Error fetching stock ledger:", err.message);
    res.status(500).json({ error: "Error fetching stock ledger" });
  }
};
